import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Tomcat vs Undertow (and Jetty, and Netty)","description":"","frontmatter":{},"headers":[],"relativePath":"todo/my_verify_docs/tomcat-vs-undertow.md","filePath":"todo/my_verify_docs/tomcat-vs-undertow.md"}'),n={name:"todo/my_verify_docs/tomcat-vs-undertow.md"};function i(r,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="tomcat-vs-undertow-and-jetty-and-netty" tabindex="-1">Tomcat vs Undertow (and Jetty, and Netty) <a class="header-anchor" href="#tomcat-vs-undertow-and-jetty-and-netty" aria-label="Permalink to &quot;Tomcat vs Undertow (and Jetty, and Netty)&quot;">​</a></h1><p>Deep-dive into the embedded servlet containers Spring Boot can run — what they are, how their thread models differ, when to pick which, and how they interact with the executor landscape already documented in this repo.</p><p>This service runs on <strong>Undertow</strong> (see <code>thread-pools-and-concurrency.md</code> — &quot;Incoming HTTP Request (Undertow worker thread)&quot;). This doc covers why, what the alternatives look like, and what the tradeoffs actually are.</p><p>Related docs:</p><ul><li><code>thread-pools-and-concurrency.md</code> — pool inventory, monitoring.</li><li><code>executor-and-pool-sizing.md</code> — how to size thread pools.</li><li><code>async-executor-and-shutdown.md</code> — graceful shutdown for <code>@Async</code>.</li></ul><hr><h2 id="_1-what-an-embedded-servlet-container-is" tabindex="-1">1. What an embedded servlet container <em>is</em> <a class="header-anchor" href="#_1-what-an-embedded-servlet-container-is" aria-label="Permalink to &quot;1. What an embedded servlet container *is*&quot;">​</a></h2><p>A <strong>servlet container</strong> is the thing that:</p><ol><li>Opens a TCP listen socket on a port (e.g., 8080).</li><li>Accepts incoming connections.</li><li>Parses HTTP bytes into a <code>HttpServletRequest</code>.</li><li>Dispatches that request to your <code>Servlet</code> (in Spring Boot, the <code>DispatcherServlet</code>).</li><li>Takes your <code>HttpServletResponse</code> and writes HTTP bytes back.</li><li>Manages the lifecycle of all the above (startup, shutdown, thread pools, timeouts).</li></ol><p>Before Spring Boot, you deployed a <code>.war</code> into a container like Tomcat that ran separately. Spring Boot <strong>embeds</strong> the container — your application is a jar that starts its own Tomcat/Undertow/Jetty instance in-process. Same HTTP semantics, different deployment model.</p><p>Spring Boot ships three options out of the box:</p><ul><li><strong>Tomcat</strong> (default) — Apache Software Foundation, 1999-present, the reference implementation many teams default to.</li><li><strong>Undertow</strong> — JBoss/Red Hat, XNIO-based, historically positioned as &quot;lightweight and fast.&quot;</li><li><strong>Jetty</strong> — Eclipse Foundation, long history, strong HTTP/2 and WebSocket support.</li></ul><p>Plus a fourth option that&#39;s <em>not</em> a servlet container:</p><ul><li><strong>Netty</strong> — via Spring WebFlux (reactive), not Spring MVC. Different programming model entirely.</li></ul><hr><h2 id="_2-the-thread-model-—-where-they-really-differ" tabindex="-1">2. The thread model — where they really differ <a class="header-anchor" href="#_2-the-thread-model-—-where-they-really-differ" aria-label="Permalink to &quot;2. The thread model — where they really differ&quot;">​</a></h2><p>The HTTP stack has two fundamentally different architectures. Understanding this is the key to understanding all three containers.</p><h3 id="model-a-thread-per-request-blocking-i-o" tabindex="-1">Model A: Thread-per-request (blocking I/O) <a class="header-anchor" href="#model-a-thread-per-request-blocking-i-o" aria-label="Permalink to &quot;Model A: Thread-per-request (blocking I/O)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[TCP accept] ──→ hand socket to a worker thread ──→ worker reads request,</span></span>
<span class="line"><span>                                                    runs DispatcherServlet,</span></span>
<span class="line"><span>                                                    writes response,</span></span>
<span class="line"><span>                                                    closes/keeps socket,</span></span>
<span class="line"><span>                                                    returns to pool.</span></span></code></pre></div><p>One worker thread per in-flight HTTP request. If you have 200 concurrent requests, you need 200 worker threads. Each thread blocks on <code>socket.read()</code> and <code>socket.write()</code>.</p><p>Pros: simple to reason about. Your code is blocking, stack traces are readable, thread-locals work.</p><p>Cons: max concurrency = worker pool size. Each thread costs ~1 MB of stack. 10K concurrent slow clients = 10K threads = 10 GB.</p><h3 id="model-b-event-loop-non-blocking-i-o-nio" tabindex="-1">Model B: Event loop (non-blocking I/O, NIO) <a class="header-anchor" href="#model-b-event-loop-non-blocking-i-o-nio" aria-label="Permalink to &quot;Model B: Event loop (non-blocking I/O, NIO)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Selector thread] ──→ watches N sockets for readiness events</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ├─ socket 17 is readable → read some bytes, parse partial request</span></span>
<span class="line"><span>     ├─ socket 22 is writable → flush buffered response bytes</span></span>
<span class="line"><span>     └─ socket 88 has new connection → accept, register for read events</span></span></code></pre></div><p>A small number of &quot;selector&quot; or &quot;I/O&quot; threads (usually <code>cores</code> of them) handle thousands of sockets non-blocking, by multiplexing via <code>epoll</code> (Linux) / <code>kqueue</code> (BSD) / IOCP (Windows). When there&#39;s <em>work</em> to do — parsed full request, need to call your handler — the work is handed off to a worker thread.</p><p>Pros: handles huge connection counts with tiny thread counts. Slow clients don&#39;t consume threads.</p><p>Cons: programming model gets harder if you expose it directly (callback hell, backpressure).</p><h3 id="the-middle-ground-nio-worker-threads" tabindex="-1">The middle ground: NIO + worker threads <a class="header-anchor" href="#the-middle-ground-nio-worker-threads" aria-label="Permalink to &quot;The middle ground: NIO + worker threads&quot;">​</a></h3><p>All modern embedded containers use <strong>NIO for the socket layer</strong> (so slow clients don&#39;t hold threads), then hand off parsed requests to a <strong>worker thread pool</strong> that runs your blocking servlet code. This is the &quot;best of both worlds&quot;: event loop for the transport, thread-per-request for the application.</p><p>All three containers do this. The differences are in <em>how</em> they wire the two halves together and how configurable each piece is.</p><hr><h2 id="_3-tomcat-—-how-it-works" tabindex="-1">3. Tomcat — how it works <a class="header-anchor" href="#_3-tomcat-—-how-it-works" aria-label="Permalink to &quot;3. Tomcat — how it works&quot;">​</a></h2><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Acceptor thread (1-2)            ← accepts new TCP connections</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Poller thread(s) (NIO selector)  ← watches sockets for I/O readiness</span></span>
<span class="line"><span>    │ (request fully read)</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Worker thread pool               ← runs DispatcherServlet</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Your @Controller method</span></span></code></pre></div><p>Tomcat&#39;s connector types:</p><ul><li><strong>NIO</strong> (<code>Http11NioProtocol</code>) — default since Tomcat 8.5. Pollers + worker pool. The normal choice.</li><li><strong>NIO2</strong> (<code>Http11Nio2Protocol</code>) — uses <code>AsynchronousSocketChannel</code>. Slightly different event plumbing; rarely gives measurable benefit.</li><li><strong>APR</strong> (Apache Portable Runtime) — native OS libraries. Faster TLS; being phased out.</li><li><strong>BIO</strong> — blocking I/O. Removed in Tomcat 8.5+.</li></ul><h3 id="thread-model" tabindex="-1">Thread model <a class="header-anchor" href="#thread-model" aria-label="Permalink to &quot;Thread model&quot;">​</a></h3><p>Two pools, visible in thread dumps:</p><ul><li><strong>Acceptor</strong> thread(s): <code>http-nio-8080-Acceptor</code>. Count: usually 1.</li><li><strong>Worker</strong> threads: <code>http-nio-8080-exec-1</code>, <code>-exec-2</code>, etc. Count: configurable, default 200 max / 10 min-spare.</li></ul><p>Key configuration (Spring Boot):</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.tomcat.threads.max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=200                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># max worker threads</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.tomcat.threads.min-spare</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=10             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># always-idle workers</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.tomcat.max-connections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=8192             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># max accepted TCP connections</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.tomcat.accept-count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=100                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># queue for accepted-but-not-handled</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.tomcat.connection-timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=20000         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ms before idle close</span></span></code></pre></div><p>Flow:</p><ul><li>Tomcat accepts up to <code>max-connections</code> TCP connections (via NIO — they don&#39;t each need a thread).</li><li>Each <em>active</em> request (one that&#39;s being handled right now) occupies one worker thread.</li><li>If all 200 workers are busy, new requests queue up to <code>accept-count=100</code>.</li><li>Beyond that, new connections are refused at the OS level.</li></ul><h3 id="defaults-are-generous" tabindex="-1">Defaults are generous <a class="header-anchor" href="#defaults-are-generous" aria-label="Permalink to &quot;Defaults are generous&quot;">​</a></h3><p>Tomcat&#39;s 200-thread default is aggressive. Many services never need that many — but it &quot;just works&quot; for most workloads, which is why it&#39;s the Spring Boot default. Sizing guidance from <code>executor-and-pool-sizing.md</code> applies directly: for I/O-bound workloads, cap it by downstream (DB pool, external rate limits).</p><hr><h2 id="_4-undertow-—-how-it-works" tabindex="-1">4. Undertow — how it works <a class="header-anchor" href="#_4-undertow-—-how-it-works" aria-label="Permalink to &quot;4. Undertow — how it works&quot;">​</a></h2><h3 id="architecture-1" tabindex="-1">Architecture <a class="header-anchor" href="#architecture-1" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XNIO worker</span></span>
<span class="line"><span>    ├─ I/O threads (event loops)       ← socket accept + read + write, non-blocking</span></span>
<span class="line"><span>    │       │</span></span>
<span class="line"><span>    │       ▼ (when a request is parsed)</span></span>
<span class="line"><span>    └─ Worker threads (blocking pool)  ← runs DispatcherServlet</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>        Your @Controller method</span></span></code></pre></div><p>Undertow is built on <strong>XNIO</strong>, a JBoss low-level I/O library. Two explicit pools, separated by role:</p><ul><li><strong>I/O threads</strong> — handle all NIO operations. Count: <code>Math.max(availableProcessors(), 2)</code> by default. Small. These must never block — they handle thousands of sockets.</li><li><strong>Worker threads</strong> — run your blocking servlet code. Count: <code>I/O threads × 8</code> by default (e.g., 16 I/O threads → 128 worker threads).</li></ul><p>This separation is more explicit than Tomcat&#39;s, though functionally similar. You&#39;ll see both pools in thread dumps:</p><ul><li><code>XNIO-1 I/O-1</code>, <code>XNIO-1 I/O-2</code>, ... — I/O threads.</li><li><code>XNIO-1 task-1</code>, <code>XNIO-1 task-2</code>, ... — worker threads.</li></ul><h3 id="configuration-in-spring-boot" tabindex="-1">Configuration in Spring Boot <a class="header-anchor" href="#configuration-in-spring-boot" aria-label="Permalink to &quot;Configuration in Spring Boot&quot;">​</a></h3><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.undertow.threads.io</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=16          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># I/O threads (event loops)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.undertow.threads.worker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=128     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># worker thread pool (blocking)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.undertow.buffer-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1024       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># per-connection buffer size</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.undertow.direct-buffers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># use off-heap buffers</span></span></code></pre></div><h3 id="what-made-undertow-notable" tabindex="-1">What made Undertow notable <a class="header-anchor" href="#what-made-undertow-notable" aria-label="Permalink to &quot;What made Undertow notable&quot;">​</a></h3><ul><li><strong>Low memory footprint</strong> — smaller heap usage per idle connection than Tomcat.</li><li><strong>Explicit I/O/worker split</strong> — clearer mental model, easier to tune for specific workloads.</li><li><strong>Native HTTP/2</strong> — had HTTP/2 support earlier than Tomcat.</li><li><strong>High raw throughput</strong> in benchmarks — often 5–15% faster than Tomcat for simple handlers, though the gap narrows or disappears for real-world Spring MVC apps where the app is the bottleneck.</li></ul><h3 id="current-status-as-of-2024-2026" tabindex="-1">Current status (as of 2024-2026) <a class="header-anchor" href="#current-status-as-of-2024-2026" aria-label="Permalink to &quot;Current status (as of 2024-2026)&quot;">​</a></h3><p>JBoss/Red Hat moved WildFly away from Undertow&#39;s stewardship in a reduced-priority mode. Undertow still works, still ships in Spring Boot 3.x, still gets security fixes — but active feature development has slowed. For new projects in 2025+, Tomcat or Jetty are often the safer long-term bets unless you have a specific reason to use Undertow.</p><p>For this service, we&#39;re on Undertow and it works well — no urgency to migrate. Worth being aware of, though, when making infrastructure decisions.</p><hr><h2 id="_5-jetty-—-the-third-option" tabindex="-1">5. Jetty — the third option <a class="header-anchor" href="#_5-jetty-—-the-third-option" aria-label="Permalink to &quot;5. Jetty — the third option&quot;">​</a></h2><h3 id="architecture-2" tabindex="-1">Architecture <a class="header-anchor" href="#architecture-2" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><p>Similar hybrid model: selector threads for NIO, worker threads for blocking application code. Pool sizing is automatic by default — Jetty tunes itself based on CPU count and load.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Acceptor threads</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Selector threads (NIO)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>QueuedThreadPool (workers)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Your @Controller method</span></span></code></pre></div><h3 id="configuration-in-spring-boot-1" tabindex="-1">Configuration in Spring Boot <a class="header-anchor" href="#configuration-in-spring-boot-1" aria-label="Permalink to &quot;Configuration in Spring Boot&quot;">​</a></h3><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.jetty.threads.max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=200</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.jetty.threads.min</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=8</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.jetty.threads.acceptors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=-1        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># auto: depends on CPU count</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.jetty.threads.selectors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=-1        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># auto</span></span></code></pre></div><h3 id="why-pick-jetty" tabindex="-1">Why pick Jetty <a class="header-anchor" href="#why-pick-jetty" aria-label="Permalink to &quot;Why pick Jetty&quot;">​</a></h3><ul><li><strong>Best HTTP/2 and WebSocket support</strong> historically.</li><li><strong>Strong alignment with Eclipse Foundation / modern Jakarta EE</strong>.</li><li><strong>Used heavily by Google infrastructure</strong> (GCP, Android build tools) — proven at scale.</li><li><strong>Competitive with Tomcat</strong> on most benchmarks.</li></ul><p>Jetty feels like &quot;Tomcat done differently&quot; — the big decision points rarely hinge on Jetty-specific features for a typical Spring Boot app.</p><hr><h2 id="_6-netty-—-the-reactive-outlier" tabindex="-1">6. Netty — the reactive outlier <a class="header-anchor" href="#_6-netty-—-the-reactive-outlier" aria-label="Permalink to &quot;6. Netty — the reactive outlier&quot;">​</a></h2><p>Netty is not a servlet container. It&#39;s a <strong>low-level asynchronous networking framework</strong>. Spring WebFlux uses Netty as its default server.</p><p>Thread model: small event-loop pool (usually <code>cores × 2</code>). All request handling, all response writing, all business logic runs on event-loop threads — which must <strong>never block</strong>.</p><p>Pros: can handle tens of thousands of concurrent connections with ~16 threads. Excellent for streaming, long-lived connections, many-slow-clients scenarios.</p><p>Cons: you must write reactive code (<code>Mono</code>, <code>Flux</code>). Blocking inside a handler poisons the event loop. Debugging is harder (no linear stack traces). Entirely different programming model.</p><p><strong>Not the same tradeoff space</strong> as Tomcat/Undertow/Jetty — you pick Netty only when you&#39;re committing to reactive programming.</p><hr><h2 id="_7-head-to-head-comparison" tabindex="-1">7. Head-to-head comparison <a class="header-anchor" href="#_7-head-to-head-comparison" aria-label="Permalink to &quot;7. Head-to-head comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Tomcat</th><th>Undertow</th><th>Jetty</th><th>Netty (WebFlux)</th></tr></thead><tbody><tr><td><strong>Model</strong></td><td>NIO + blocking workers</td><td>XNIO + blocking workers</td><td>NIO + blocking workers</td><td>Pure reactive event loop</td></tr><tr><td><strong>Spring Boot default</strong></td><td>✅</td><td>—</td><td>—</td><td>✅ for WebFlux</td></tr><tr><td><strong>Thread pool for handlers</strong></td><td>1 pool (workers)</td><td>2 pools (I/O + workers)</td><td>1 pool (QueuedThreadPool)</td><td>Event loop only</td></tr><tr><td><strong>Default worker count</strong></td><td>200</td><td>~128 (cores × 8)</td><td>200</td><td>~16 (cores × 2)</td></tr><tr><td><strong>Memory per idle connection</strong></td><td>~30 KB</td><td>~10-15 KB</td><td>~20 KB</td><td>~5 KB</td></tr><tr><td><strong>HTTP/2 support</strong></td><td>✅</td><td>✅</td><td>✅ (strong)</td><td>✅</td></tr><tr><td><strong>HTTP/3 support</strong></td><td>Experimental</td><td>No active work</td><td>Experimental</td><td>✅ (via netty-incubator)</td></tr><tr><td><strong>Virtual threads (Java 21+)</strong></td><td>✅ (3.2+ via <code>spring.threads.virtual.enabled</code>)</td><td>✅</td><td>✅</td><td>N/A (already non-blocking)</td></tr><tr><td><strong>Active development</strong></td><td>Very active</td><td>Reduced</td><td>Active</td><td>Very active</td></tr><tr><td><strong>Complexity of tuning</strong></td><td>Simple</td><td>Moderate (two pools)</td><td>Simple-ish</td><td>High</td></tr><tr><td><strong>Best for</strong></td><td>Default choice, broad ecosystem</td><td>Low-memory deployments</td><td>HTTP/2 / WebSocket heavy</td><td>High-concurrency reactive</td></tr></tbody></table><h3 id="performance-in-practice" tabindex="-1">Performance in practice <a class="header-anchor" href="#performance-in-practice" aria-label="Permalink to &quot;Performance in practice&quot;">​</a></h3><p>Microbenchmarks (Techempower, etc.) show all three blocking containers within ~15% of each other. In production Spring Boot apps, the <strong>container is almost never the bottleneck</strong> — your DB, external HTTP calls, or business logic are. Swapping Tomcat for Undertow almost never moves the P99 needle.</p><p><strong>Pick for operational reasons</strong> (ecosystem, memory footprint, team familiarity), not for marginal throughput differences.</p><hr><h2 id="_8-switching-containers-in-spring-boot" tabindex="-1">8. Switching containers in Spring Boot <a class="header-anchor" href="#_8-switching-containers-in-spring-boot" aria-label="Permalink to &quot;8. Switching containers in Spring Boot&quot;">​</a></h2><p>One line in <code>pom.xml</code>. Exclude the default starter&#39;s Tomcat, include the replacement starter:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.springframework.boot&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;spring-boot-starter-web&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">exclusions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">exclusion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.springframework.boot&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;spring-boot-starter-tomcat&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">exclusion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">exclusions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.springframework.boot&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;spring-boot-starter-undertow&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>No code changes. The same <code>@RestController</code> runs on any of them.</p><hr><h2 id="_9-virtual-threads-and-the-containers-java-21" tabindex="-1">9. Virtual threads and the containers (Java 21+) <a class="header-anchor" href="#_9-virtual-threads-and-the-containers-java-21" aria-label="Permalink to &quot;9. Virtual threads and the containers (Java 21+)&quot;">​</a></h2><p>Spring Boot 3.2+ supports virtual threads via:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.threads.virtual.enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span></code></pre></div><p>What this changes per container:</p><ul><li><strong>Tomcat</strong> — the worker pool becomes a <code>VirtualThreadPerTaskExecutor</code>. Each request runs on its own virtual thread. The 200-thread cap is gone; scale limited only by memory and downstream.</li><li><strong>Undertow</strong> — same idea; worker thread pool is replaced by virtual-thread-per-task.</li><li><strong>Jetty</strong> — same.</li><li><strong>Netty</strong> — not applicable (WebFlux doesn&#39;t use blocking worker threads in the first place).</li></ul><p>The implication: <strong>with virtual threads, the container&#39;s worker pool sizing stops mattering much.</strong> You can accept 50,000 concurrent requests on a Tomcat pod without tuning <code>server.tomcat.threads.max</code>. The practical limit becomes DB connections, external service rate limits, and memory — not thread count.</p><p>Caveats from <code>executor-deep-dive.md</code> §6 still apply:</p><ul><li><code>synchronized</code> blocks pin virtual threads to carriers. Heavy synchronized use defeats the benefit. (Fixed in JDK 24.)</li><li>Thread-local caches sized for &quot;200 threads&quot; now see 50,000 copies — memory bloat.</li><li>DB connection pool (10 connections) will get exhausted near-instantly at high concurrency unless you add a <code>Semaphore</code> gate.</li></ul><p>For this service: the stage executor and audit executor are separate executors <em>beyond</em> the container&#39;s worker pool. Switching the container to virtual threads doesn&#39;t automatically make them virtual — they&#39;re explicit <code>ThreadPoolExecutor</code>s. You&#39;d flip them separately.</p><hr><h2 id="_10-where-the-container-sits-in-this-service" tabindex="-1">10. Where the container sits in this service <a class="header-anchor" href="#_10-where-the-container-sits-in-this-service" aria-label="Permalink to &quot;10. Where the container sits in this service&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client HTTP request</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Undertow XNIO I/O thread      ← reads bytes, parses HTTP, accepts connection</span></span>
<span class="line"><span>    ↓ (hand off parsed request)</span></span>
<span class="line"><span>Undertow worker thread         ← runs DispatcherServlet</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>VerifyApiController.verify()</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>VerifyApiService (on same worker thread)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>StageExecutor.execute(...)</span></span>
<span class="line"><span>    ├─→ traceableExecutorService (separate 16-thread pool)</span></span>
<span class="line"><span>    ├─→ taskExecutor (separate 4-8 thread pool, @Async audit)</span></span>
<span class="line"><span>    └─→ ... </span></span>
<span class="line"><span>    ↓ (all stages complete)</span></span>
<span class="line"><span>Worker thread resumes, builds response</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Undertow XNIO I/O thread       ← writes bytes back to socket</span></span></code></pre></div><p>Four distinct thread pools involved:</p><ol><li><strong>XNIO I/O threads</strong> (Undertow, small, non-blocking socket handling).</li><li><strong>Undertow worker threads</strong> (handle servlet logic — initial controller + response assembly).</li><li><strong><code>traceableExecutorService</code></strong> (16 threads — fan out verification stages in parallel).</li><li><strong><code>taskExecutor</code></strong> (4-8 threads — <code>@Async</code> audit work).</li></ol><p>The <code>thread-pools-and-concurrency.md</code> inventory was from the perspective of the application pools. The container pools are additional — they&#39;re the entry point.</p><hr><h2 id="_11-tuning-and-monitoring-per-container" tabindex="-1">11. Tuning and monitoring per container <a class="header-anchor" href="#_11-tuning-and-monitoring-per-container" aria-label="Permalink to &quot;11. Tuning and monitoring per container&quot;">​</a></h2><h3 id="tomcat" tabindex="-1">Tomcat <a class="header-anchor" href="#tomcat" aria-label="Permalink to &quot;Tomcat&quot;">​</a></h3><p>Metrics (via Spring Boot Actuator + Micrometer):</p><ul><li><code>tomcat.threads.busy</code> — active workers.</li><li><code>tomcat.threads.current</code> — total pool size.</li><li><code>tomcat.threads.config.max</code> — configured max.</li><li><code>tomcat.sessions.*</code> — session metrics (if you use sessions).</li></ul><p>Signs of trouble:</p><ul><li><code>busy</code> pinned at <code>max</code> → pool saturated, requests queueing or rejected.</li><li>Slow downstream + high <code>busy</code> → downstream is really the problem.</li></ul><h3 id="undertow" tabindex="-1">Undertow <a class="header-anchor" href="#undertow" aria-label="Permalink to &quot;Undertow&quot;">​</a></h3><p>Undertow exposes fewer metrics out of the box. Use JMX or the per-pool <code>executor.*</code> metrics if you can get the thread pool beans. Common gauges:</p><ul><li>Worker pool size and active count (from thread dumps or Actuator).</li><li>XNIO I/O thread count (fixed at startup).</li></ul><p>Watch in thread dumps:</p><ul><li>Many <code>XNIO-*-task-*</code> threads in <code>RUNNABLE</code> or <code>TIMED_WAITING</code> on I/O → normal under load.</li><li>All workers blocked on DB connection acquisition → downstream bottleneck.</li></ul><h3 id="jetty" tabindex="-1">Jetty <a class="header-anchor" href="#jetty" aria-label="Permalink to &quot;Jetty&quot;">​</a></h3><ul><li><code>jetty.threads.busy</code>, <code>.config.min</code>, <code>.config.max</code>.</li><li><code>jetty.threads.jobs</code> — queued jobs (backlog).</li></ul><hr><h2 id="_12-common-questions-deep-dive-topics" tabindex="-1">12. Common questions &amp; deep-dive topics <a class="header-anchor" href="#_12-common-questions-deep-dive-topics" aria-label="Permalink to &quot;12. Common questions &amp; deep-dive topics&quot;">​</a></h2><h3 id="q-does-swapping-tomcat-for-undertow-make-my-app-faster" tabindex="-1">Q: Does swapping Tomcat for Undertow make my app faster? <a class="header-anchor" href="#q-does-swapping-tomcat-for-undertow-make-my-app-faster" aria-label="Permalink to &quot;Q: Does swapping Tomcat for Undertow make my app faster?&quot;">​</a></h3><p>Usually no. The container is rarely the bottleneck for a Spring Boot app doing real work (DB queries, external HTTP calls). You might see 5-15% on synthetic &quot;hello world&quot; benchmarks; on real workloads, usually unmeasurable.</p><p><strong>Switch for operational reasons</strong> (memory footprint, ecosystem fit, specific feature), not for generic &quot;performance.&quot;</p><h3 id="q-how-do-i-know-how-many-worker-threads-my-container-is-using-right-now" tabindex="-1">Q: How do I know how many worker threads my container is using right now? <a class="header-anchor" href="#q-how-do-i-know-how-many-worker-threads-my-container-is-using-right-now" aria-label="Permalink to &quot;Q: How do I know how many worker threads my container is using right now?&quot;">​</a></h3><p>Thread dump (<code>jcmd &lt;pid&gt; Thread.print</code>). Count threads matching the container&#39;s naming pattern:</p><ul><li>Tomcat: <code>http-nio-8080-exec-*</code></li><li>Undertow: <code>XNIO-*-task-*</code></li><li>Jetty: <code>qtp*</code></li></ul><p>Or use Actuator metrics (see §11).</p><h3 id="q-my-requests-are-timing-out-under-load-is-my-pool-too-small" tabindex="-1">Q: My requests are timing out under load. Is my pool too small? <a class="header-anchor" href="#q-my-requests-are-timing-out-under-load-is-my-pool-too-small" aria-label="Permalink to &quot;Q: My requests are timing out under load. Is my pool too small?&quot;">​</a></h3><p>Sequence:</p><ol><li>Check <code>tomcat.threads.busy</code> (or equivalent). At max? Pool is saturated.</li><li>Check thread dump: what are the workers <em>doing</em>? If they&#39;re all blocked on <code>HikariPool.getConnection()</code>, the DB pool is the bottleneck — more worker threads won&#39;t help.</li><li>If threads are running CPU-heavy code, you&#39;re CPU-bound — scaling workers just adds context-switching.</li><li>If they&#39;re waiting on external HTTP calls, scale workers up (but also check those services aren&#39;t rate-limiting you).</li></ol><p>See <code>executor-and-pool-sizing.md</code> for the full decision tree.</p><h3 id="q-what-s-max-connections-vs-max-threads" tabindex="-1">Q: What&#39;s <code>max-connections</code> vs <code>max-threads</code>? <a class="header-anchor" href="#q-what-s-max-connections-vs-max-threads" aria-label="Permalink to &quot;Q: What&#39;s \`max-connections\` vs \`max-threads\`?&quot;">​</a></h3><ul><li><strong><code>max-connections</code></strong> (Tomcat-specific term) — max accepted TCP connections. NIO means the container can hold many connections open with few threads.</li><li><strong><code>max-threads</code></strong> (worker threads) — max concurrent <em>requests being actively processed</em>.</li></ul><p>A slow client holding a connection open doesn&#39;t consume a thread. Only an <em>active request</em> consumes a thread. So <code>max-connections</code> can be much larger than <code>max-threads</code> — that&#39;s the whole point of NIO.</p><h3 id="q-should-i-use-accept-count-to-queue-requests-or-reject-early" tabindex="-1">Q: Should I use <code>accept-count</code> to queue requests, or reject early? <a class="header-anchor" href="#q-should-i-use-accept-count-to-queue-requests-or-reject-early" aria-label="Permalink to &quot;Q: Should I use \`accept-count\` to queue requests, or reject early?&quot;">​</a></h3><p>Queueing helps smooth transient bursts. Rejecting early gives faster feedback to the client (503 retry now vs timeout later).</p><p>For user-facing APIs: small <code>accept-count</code> (10-50), fast rejection, client retries with backoff. For internal services with retry-capable clients: larger <code>accept-count</code> (100-500), absorb bursts.</p><h3 id="q-connection-keep-alive-and-threads" tabindex="-1">Q: Connection keep-alive and threads <a class="header-anchor" href="#q-connection-keep-alive-and-threads" aria-label="Permalink to &quot;Q: Connection keep-alive and threads&quot;">​</a></h3><p>HTTP keep-alive keeps the TCP connection open across requests. With NIO, this doesn&#39;t consume a worker thread between requests — only the connection slot (<code>max-connections</code>). So keep-alive is nearly free in terms of threads. It saves TCP handshake cost on the next request.</p><h3 id="q-how-does-https-tls-interact-with-the-container" tabindex="-1">Q: How does HTTPS / TLS interact with the container? <a class="header-anchor" href="#q-how-does-https-tls-interact-with-the-container" aria-label="Permalink to &quot;Q: How does HTTPS / TLS interact with the container?&quot;">​</a></h3><p>TLS adds CPU cost (handshake = asymmetric crypto, bulk = symmetric). Tomcat and Undertow both do TLS termination on the I/O thread. For very high TLS traffic, offloading to a separate proxy (nginx, Envoy) or using native acceleration (Tomcat APR, JDK 21+ AES-GCM intrinsics) can help. Rarely the bottleneck for typical Spring Boot apps.</p><h3 id="q-can-i-run-two-containers-simultaneously-different-ports" tabindex="-1">Q: Can I run two containers simultaneously (different ports)? <a class="header-anchor" href="#q-can-i-run-two-containers-simultaneously-different-ports" aria-label="Permalink to &quot;Q: Can I run two containers simultaneously (different ports)?&quot;">​</a></h3><p>Yes, but it&#39;s unusual. Easier pattern: one container with two connectors (Tomcat supports multiple <code>&lt;Connector&gt;</code> elements, Undertow supports multiple listeners). Spring Boot Actuator does this — the management endpoint can run on a separate port via <code>management.server.port</code>.</p><h3 id="q-what-about-http-2-and-http-3" tabindex="-1">Q: What about HTTP/2 and HTTP/3? <a class="header-anchor" href="#q-what-about-http-2-and-http-3" aria-label="Permalink to &quot;Q: What about HTTP/2 and HTTP/3?&quot;">​</a></h3><ul><li><strong>HTTP/2</strong>: supported by all three (Tomcat, Undertow, Jetty). Multiplexing means many requests share one TCP connection — reduces connection count, keeps the thread-per-request model.</li><li><strong>HTTP/3 (QUIC/UDP)</strong>: experimental in most containers. Netty leads. If you need HTTP/3, go reactive.</li></ul><h3 id="q-how-does-graceful-shutdown-work-per-container" tabindex="-1">Q: How does graceful shutdown work per container? <a class="header-anchor" href="#q-how-does-graceful-shutdown-work-per-container" aria-label="Permalink to &quot;Q: How does graceful shutdown work per container?&quot;">​</a></h3><p>Spring Boot 2.3+ has <code>server.shutdown=graceful</code>:</p><ol><li>Stop accepting new connections.</li><li>Let in-flight requests complete up to <code>spring.lifecycle.timeout-per-shutdown-phase</code> (default 30s).</li><li>Force-close after timeout.</li></ol><p>All three containers support this via Spring Boot&#39;s unified abstraction. Confirms with log lines like <code>Commencing graceful shutdown. Waiting for active requests to complete</code>.</p><h3 id="q-what-happens-when-the-container-s-pool-saturates-but-the-traceableexecutorservice-is-idle" tabindex="-1">Q: What happens when the container&#39;s pool saturates but the <code>traceableExecutorService</code> is idle? <a class="header-anchor" href="#q-what-happens-when-the-container-s-pool-saturates-but-the-traceableexecutorservice-is-idle" aria-label="Permalink to &quot;Q: What happens when the container&#39;s pool saturates but the \`traceableExecutorService\` is idle?&quot;">​</a></h3><p>Bad news: the request never reaches the stage executor, because there&#39;s no Undertow worker to call it. The bottleneck is at the container, not the downstream pool.</p><p>This is a common misdiagnosis — someone looks at <code>traceableExecutorService</code> metrics, sees idle threads, and wonders why throughput is low. Answer: Undertow workers are all busy waiting on something, so no new requests get dispatched to the stage executor at all.</p><h3 id="q-does-virtualthreadpertaskexecutor-eliminate-the-need-for-the-stage-executor" tabindex="-1">Q: Does <code>virtualThreadPerTaskExecutor</code> eliminate the need for the stage executor? <a class="header-anchor" href="#q-does-virtualthreadpertaskexecutor-eliminate-the-need-for-the-stage-executor" aria-label="Permalink to &quot;Q: Does \`virtualThreadPerTaskExecutor\` eliminate the need for the stage executor?&quot;">​</a></h3><p>Not automatically. Switching Undertow workers to virtual threads means the <em>container layer</em> scales. But the stage executor is an explicit fan-out pattern — multiple stages run in parallel per request. Even with virtual worker threads, you&#39;d still want a separate executor (virtual or otherwise) to manage the fan-out, context propagation, and backpressure.</p><p>However: if worker threads are virtual, the stage executor could also be <code>newVirtualThreadPerTaskExecutor()</code>, removing the 16-thread cap. Tradeoff as in <code>executor-deep-dive.md</code> §6 — worth measuring.</p><h3 id="q-what-if-i-want-to-serve-both-servlet-and-reactive-routes" tabindex="-1">Q: What if I want to serve both servlet and reactive routes? <a class="header-anchor" href="#q-what-if-i-want-to-serve-both-servlet-and-reactive-routes" aria-label="Permalink to &quot;Q: What if I want to serve both servlet and reactive routes?&quot;">​</a></h3><p>Possible but awkward. Spring Boot supports either Spring MVC (servlet) <em>or</em> WebFlux (reactive) as the primary stack. You can embed a separate reactive endpoint via a sidecar or a separate Spring context, but the ergonomics aren&#39;t great. Usually: pick one.</p><hr><h2 id="_13-mental-model" tabindex="-1">13. Mental model <a class="header-anchor" href="#_13-mental-model" aria-label="Permalink to &quot;13. Mental model&quot;">​</a></h2><ul><li>A <strong>servlet container</strong> = TCP listen socket + HTTP parser + thread pool + servlet dispatcher.</li><li>All three (Tomcat, Undertow, Jetty) use <strong>NIO for sockets + blocking worker pool for handlers</strong>. The differences are mostly naming, pool structure, and defaults.</li><li><strong>Netty (WebFlux)</strong> is a different paradigm — everything runs on an event loop, no per-request thread.</li><li><strong>Pick by operational fit</strong>, not by microbenchmarks. Most Spring Boot bottlenecks are in the app, not the container.</li><li><strong>Virtual threads (3.2+)</strong> largely eliminate worker-pool sizing concerns, but don&#39;t change anything about the I/O layer (which was already non-blocking).</li><li>This service runs <strong>Undertow</strong>. It works. No strong reason to change until the larger ecosystem question (active development) forces a migration.</li></ul><hr><h2 id="_14-follow-up-topics-for-future-deep-dives" tabindex="-1">14. Follow-up topics (for future deep-dives) <a class="header-anchor" href="#_14-follow-up-topics-for-future-deep-dives" aria-label="Permalink to &quot;14. Follow-up topics (for future deep-dives)&quot;">​</a></h2><ul><li><strong>Undertow&#39;s XNIO API</strong> — how the event loop plumbing actually works under the hood.</li><li><strong>Tomcat&#39;s <code>NioEndpoint</code> internals</strong> — Acceptor/Poller/Worker handoff mechanics.</li><li><strong>HTTP/2 multiplexing</strong> — how one TCP connection carrying 100 streams interacts with the thread-per-request model.</li><li><strong>Keep-alive tuning</strong> — timeouts, max requests per connection, impact on pooling.</li><li><strong>TLS tuning</strong> — session resumption, OCSP stapling, cipher preference.</li><li><strong>Access logging</strong> — each container&#39;s built-in access log format and how to route to a file or stdout.</li><li><strong>Spring Boot Actuator and container metrics</strong> — which metrics are auto-exposed, which need manual wiring.</li><li><strong>Behind a load balancer / proxy</strong> — X-Forwarded-For handling, <code>server.forward-headers-strategy</code>, trust boundaries.</li><li><strong>WebSocket handling</strong> — per-container upgrade paths, idle timeouts, thread attribution.</li><li><strong>Reactive server in a non-reactive app</strong> — using WebClient from a Tomcat-based service without swapping to WebFlux.</li><li><strong>Java 21 virtual threads + container</strong> — benchmarks, pinning, thread-local memory implications.</li><li><strong>Graceful shutdown edge cases</strong> — long-running requests, streaming responses, in-flight <code>@Async</code>.</li><li><strong>Container security hardening</strong> — header limits, URI length limits, connection rate limits, timeout tuning.</li></ul>`,163)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
